# 批注数据：src/utils/settings/settings.ts
# slug = src_utils_settings_settings_ts
# 锚点规则：函数统一用 before 落在「声明首行」（恰好在 /** */ 文档块之后），
# 块注释内部、多行表达式首行、模板字符串内部一律不放锚点。
ANNOTATIONS = [
    (58, 'before', '''拼出受管设置文件路径：取受管目录再接 managed-settings.json。这是所有「文件型受管设置」的总入口，后面的 drop-in 目录也由同一目录派生。'''),
    (74, 'before', '''加载「文件型受管设置」：先读 managed-settings.json 作底（优先级最低），再按字母序读 managed-settings.d/ 下的碎片文件逐层覆盖（后到者胜）。这套「基文件 + drop-in」约定照搬 systemd / sudoers，让不同团队能各自发独立策略片段而不必抢改同一个管理员文件。导出给测试用。'''),
    (127, 'before', '''只判断「文件型受管设置」里有哪些来源存在（基文件 / drop-in / 两者都有），供 /status 显示括号标注，例如「(file)」「(drop-ins)」「(file + drop-ins)」。不返回具体值，只回布尔。'''),
    (157, 'before', '''统一处理读设置时的文件系统错误：若是 ENOENT（断链或文件缺失）只打调试日志；其他错误才正式记录。避免把「文件不存在」当成异常刷屏。'''),
    (178, 'before', '''把单个设置文件解析成「结构化数据 + 校验错误」两份。带缓存：命中缓存先克隆一份再返回，防止调用方（mergeWith、updateSettingsForSource）改到缓存里的对象。'''),
    (201, 'before', '''parseSettingsFile 的「无缓存」真身：先安全解析路径、读文件；空文件当空对象；在 schema 校验前先过滤掉非法权限规则，避免一条坏规则导致整份文件被拒；最后用 SettingsSchema 安全解析，失败则把「规则警告 + 校验错误」一起回传。读文件出错时按文件系统错误统一处理。'''),
    (239, 'before', '''根据来源类型返回该设置文件所在的根目录：用户设置取配置主目录；项目 / 本地 / 策略设置取原始工作目录；flag 设置取其指定路径的父目录（没给则用原始工作目录兜底）。'''),
    (264, 'before', '''按「协作模式」决定用户设置文件名：开了 cowork 插件或环境变量 CLAUDE_CODE_USE_COWORK_PLUGINS 时用 cowork_settings.json，否则用 settings.json。优先级是「会话状态 → 环境变量 → 默认」。'''),
    (274, 'before', '''按来源类型拼出设置文件的完整路径：用户来源接文件名；项目 / 本地来源接相对路径；策略来源指向受管文件；flag 来源用命令行指定的路径。每种来源的「根目录」由上一个函数统一算。'''),
    (297, 'before', '''只回「相对」路径片段：项目设置是 .claude/settings.json，本地设置是 .claude/settings.local.json。本地设置带 .local 后缀，正是后面会被自动加进 .gitignore 的那一份。'''),
    (309, 'before', '''取「单个来源」的已合并设置，带缓存：命中直接返回，否则走无缓存版本并写回缓存。这里只返回该来源自身的内容，不涉及多来源合并。'''),
    (319, 'before', '''单来源的「真实读取」：对策略来源走「先到先得」——远程 > MDM(plist/HKLM) > 受管文件 > HKCU，取第一个有内容的；其余来源直接解析对应文件。flag 来源还会把 SDK 内联设置合并进去。注意缓存绕过：因为下面的 mergeWith 会改动目标对象，若复用缓存对象会在写入失败前泄漏未持久化状态。'''),
    (375, 'before', '''返回「当前生效的策略来源」里优先级最高者出自哪里：远程 > 管理员 MDM（macOS 标 plist、其他标 hklm）> 受管文件 > HKCU。用来在界面上标注策略来自哪一层，方便排障。'''),
    (416, 'before', '''把设置「写回」某个可编辑来源。策略与 flag 来源不可写，直接返回成功；其余来源先建目录、绕过单来源缓存读现有内容（避免 mergeWith 改动缓存对象），再把新旧合并后落盘。合并语义很讲究：数组直接整体替换（调用方自己算好终态）、undefined 表示「删键」、其余走 lodash 默认深合并。写入前标记内部写、写后用 resetSettingsCache 让会话缓存失效；本地来源还会异步加进 .gitignore。'''),
    (529, 'before', '''数组合并的辅助：把目标数组与源数组合并后去重（uniq），用于「允许 / 拒绝」这类列表型字段的累加而非覆盖。'''),
    (538, 'before', '''lodash mergeWith 的自定义合并器：两边都是数组时走「拼接 + 去重」（mergeArrays）；否则返回 undefined 让 lodash 走默认合并。这是全文件合并语义的核心，保证列表型字段累加、对象型字段递归合并。'''),
    (558, 'before', '''为日志提炼「设置键名列表」：先用 schema 的 strip 只留合法字段，再对 permissions / sandbox / hooks 这三类展开一层嵌套（如 permissions.allow），其余只回顶层键。返回的键按字典序排好，便于审计日志展示。'''),
    (645, 'before', '''真正「从磁盘合并全部来源」的原始实现（无缓存）。用 isLoadingSettings 标志防递归；从「插件设置」这层最低优先级起步，再按启用来源顺序逐层深合并。策略来源走「先到先得」并去重错误；其余来源按文件路径解析、跳过重复文件、合并内联 flag 设置。全程打诊断埋点。这是设置系统的主入口之一。'''),
    (812, 'before', '''返回「合并后的有效设置」快照（至少空对象）。组件若需要响应式更新应改用 useSettings 钩子；普通逻辑拿这份快照即可。'''),
    (820, 'before', '''向后兼容别名：等于 getInitialSettings。旧调用方没改完之前保留这个出口。'''),
    (822, 'before', '''导出类型：把「有效设置」和「各来源原文（按优先级从低到高）」打包在一起，方便上层同时拿到合并结果与每一层的原始值。'''),
    (836, 'before', '''同时返回「有效合并设置」与「按优先级排好的各来源原文」。注意它每次都先 resetSettingsCache，保证即使磁盘变化监听器还没触发，effective 与 sources 也基于同一份磁盘状态，两者一致。'''),
    (856, 'before', '''返回「合并设置 + 全部校验错误」，带会话级缓存（设置变更需重启，所以整会话缓存都有效）。缓存未命中才落盘加载并写回缓存。'''),
    (882, 'before', '''判断「是否有可信来源接受过『跳过危险模式权限弹窗』」。故意排除项目设置：否则恶意项目能自己绕过弹窗（RCE 风险）。只看用户 / 本地 / flag / 策略四者。'''),
    (896, 'before', '''判断「是否有可信来源开启了自动模式」。同样排除项目设置以防恶意项目控制。仅当 TRANSCRIPT_CLASSIFIER 特性开启时才生效，否则直接返回 false；命中后会打一条调试日志把各来源的值都印出来。'''),
    (918, 'before', '''判断「计划模式是否采用自动模式语义」，默认开启（opt-out）。只要「任一可信来源」显式设 false 就返回 false；项目设置被排除，防止恶意项目左右这个开关。'''),
    (936, 'before', '''从可信来源合并出「自动模式的配置」（allow / soft_deny / environment 三类列表）。同样排除项目设置；仅当 TRANSCRIPT_CLASSIFIER 开启才有值，否则返回 undefined。注意 USER_TYPE 为 ant 时把 deny 也并入 soft_deny。'''),
    (984, 'before', '''不依赖校验、直接扫描各「用户可配置」来源的原始文件，看是否出现过某个键。用来探测「用户意图」——比如用户设了 cleanupPeriodDays 但别处校验失败，仍能据此判断他确实配过清理，从而跳过清理而非回退默认。策略来源被跳过（那不是用户自己配的）。'''),
]
